        FCC     "Macro anlegen: Kennung?"

msgMacroName:
        FCB     $13,$00,$C0,$01,$98,$09,$09,$09,$09,$09,$09,$09
        FCC     ": Name? "

msgPressKey:
        FCB     $2C,$00,$C0,$01,$98,$09,$09,$09,$09,$09,$09,$09,$09,$09,$09,$09
        FCB     $09,$09,$09,$09,$09,$09,$09,$09,$09,$09,$09,$09,$09,$09,$09,$09
        FCC     "Weiter: Taste"

