        FCB     $2C,$00,$C0,$01,$98
        FCC     "Macro abgeschlossen.                    "

msgLoadingExtra:
        FCB     $2C,$00,$C0,$01,$98
        FCC     "Zusatzsoftware wird geladen             "

msgTelesoftFile:
        FCB     $18,$00,$C0,$01,$98
        FCC     "Telesoftware: File? "

msgTelesoftPage:
        FCB     $2C,$00,$C0,$01,$98
        FCC     "Telesoftware-Seite  aufrufen!           "
        FCC     " "

