msgNoTelesoft:
        FCB     $2C,$00,$C0,$01,$98
        FCC     "Keine Telesoftw. im Macro! Weiter: Taste"

; String table: 31 little-endian pointers, ROM $BA18-$BA55, runtime $1670-$16AD.
;
; This is how the text is reached - nothing addresses a record directly, which is
; why searching for pointers to the visible strings came up empty. Each entry
; points at a record header, not at the text:
;
;     [0] $11F8  18 00 C0 01 98  "von Diskette: File? "
;     [3] $126B  2C 00 C0 01 98  "Load Capture Display Macro Xfer Screen  "
;     [4] $1298  2C 00 C0 01 98  "ASCII Btx Keybd Telesoft Edit Pause Quit"
;
; A record is five header bytes followed by the text. Header byte 0 is the record
; length minus one, which is what makes the stride vary: $2C gives a 45-byte
; record with 40 characters, $18 a 25-byte record with 20, $04 a 5-byte record
; with none. Byte 1 is always $00 and byte 4 always $98; bytes 2 and 3 vary
; ($C0/$80, $01/$07) and look like display parameters, not yet established.
;
; The earlier reading of these five bytes as a trailer was wrong - they lead the
; record, and the pointers here prove it.
c64StrTable:
        DW      msgLoadFile,msgBlank,msgNoFile,msgMenu1,msgMenu2,msgCaptureOn,msgShowBuffer,msgSaveFile
        DW      msgBufferFull,msgErrLine,msgRetry,msgMacroRun,msgMacroLabel,msgNoDrive,msgPrinterOrFile,msgNoPrinter
        DW      msgKeyboard,msgMonitorOn,msgMonitorOff,msgPauseAsk,msgPauseWait,msgMacroNew,msgMacroName,msgPressKey
        DW      msgMacroDone,msgLoadingExtra,msgTelesoftFile,msgTelesoftPage,msgLoadingData,msgBadFormat,msgNoTelesoft

c64ColdStart:
; vector 0 $1000 - cold start: IOINIT/RESTOR/PCINT/INITCZ/CLALL, clear zero page, hook CINV to the decoder IRQ, enable the decoder interrupt
        LDA     #$00
        STA     $D016
        JSR     IOINIT
        LDA     #$00
        TAY

L16B9:
        STA     >$0002,Y
        STA     BUF,Y
        STA     IERROR,Y
        INY
        BNE     L16B9
        JSR     SIZE+8
        JSR     RESTOR
        JSR     PCINT
        JSR     INITCZ
        JSR     CLALL
        LDA     #$00
        STA     btxFifo00
        STA     btxCellReady
        SEI
        LDA     #L2359&255
        STA     CINV
        LDA     #L2359>>8
        STA     CINV+1
        LDA     btxIrqAck
        LDA     #$40
        STA     btxIrqCtrl
        LDA     btxIrqArmB
        STA     btxIrqArmB
        LDA     btxIrqArmA
        STA     btxIrqArmA
        CLI
        JSR     c64LoadExtra

c64StartSession:
; vector 1 $1003 - show the splash, send ceptStartPage to the decoder, reset the capture-buffer pointers and mode flags
        JSR     INIT
        LDA     btxSessionUp
        BNE     L172D
        LDA     #$FF
        STA     btxSessionUp
        LDA     HELPIC
        STA     ZPHELP
        LDA     HELPIC+1
        STA     ZPHELPHi
        LDA     #$FF
        STA     btxHostActive

L171B:
        LDY     #$00
        LDA     (ZPHELP),Y
        BEQ     L172D
        JSR     TOBTX
        INC     ZPHELP
        BNE     L172A
        INC     ZPHELPHi

L172A:
        JMP     L171B

L172D:
        LDA     CAPPUF
        STA     CAPBIS
        LDA     CAPPUF+1
        STA     CAPBIS+1
        LDA     #$00
        STA     CAPFLG
        STA     MAKFLG
        LDA     #$00
        STA     DTKBD
        STA     EDTFLG
        STA     c64AlphaFlag

c64MainLoop:
; vector 2 $1006 - main loop: fetch a key, STOP ends a capture, F7 ($88) opens the menu, anything else goes to c64SendKey
        LDA     #$FF
        STA     btxHostActive

L1751:
        SEI
        LDA     CODE1
        CLI
        BIT     CAPFLG
        BPL     L175E
        JSR     CAPROU

L175E:
        JSR     GETAST
        BCS     L1751
        CMP     #$03
        BNE     L176D
        JSR     CAPOFF
        JMP     L177F

L176D:
        CMP     #$88
        BNE     L177C
        BIT     CAPFLG
        BMI     L177C
        JSR     SPECAL
        JMP     L177F

L177C:
        JSR     SENCOD

L177F:
        JMP     L1751

c64SendKey:
; vector 3 $1009 - translate one key with c64XlatKey and send the resulting 1-3 CEPT bytes to the decoder
        CMP     #$8B
        BNE     L1789
        JSR     CAPOFF

L1789:
        CMP     #$8C
        BNE     L1790
        JSR     CAPOFF

L1790:
        JSR     CODCH
        BCS     L17B5
        LDA     c64AlphaFlag
        BEQ     L179F
        LDA     CODE1
        BMI     L17B5

L179F:
        LDA     CODE1
        JSR     TOBTX
        LDA     CODE2
        BEQ     L17AD
        JSR     TOBTX

L17AD:
        LDA     CODE3
        BEQ     L17B5
        JSR     TOBTX

L17B5:
        RTS

c64XlatKey:
; vector 5 $100F - PETSCII key -> CEPT, via c64AsciiKeys (2-byte records, alpha mode), then c64GermanKeys, then c64CtrlKeys (4-byte records). C=1 when the key has no mapping
        LDX     #$00
        STX     CODE1
        STX     CODE2
        STX     CODE3
        LDX     DTKBD
        BEQ     L180D
        LDX     c64AlphaFlag
        BEQ     L17EF
        LDX     #c64AsciiKeys&255
        STX     KBDPTR
        LDX     #c64AsciiKeys>>8
        STX     KBDPTRHi
        LDY     #$00

L17D5:
        TAX
        LDA     (KBDPTR),Y
        BEQ     L17EE
        TXA
        CMP     (KBDPTR),Y
        BEQ     L17E4
        INY
        INY
        JMP     L17D5

L17E4:
        INY
        LDA     (KBDPTR),Y
        BEQ     L185B
        STA     CODE1
        CLC
        RTS

L17EE:
        TXA

L17EF:
        LDX     DINTAB
        STX     KBDPTR
        LDX     DINTAB+1
        STX     KBDPTRHi
        LDY     #$00

L17FB:
        TAX
        LDA     (KBDPTR),Y
        BEQ     L180C
        TXA
        CMP     (KBDPTR),Y
        BEQ     L185D
        INY
        INY
        INY
        INY
        JMP     L17FB

L180C:
        TXA

L180D:
        LDX     ASCTAB
        STX     KBDPTR
        LDX     ASCTAB+1
        STX     KBDPTRHi
        LDY     #$00

L1819:
        TAX
        LDA     (KBDPTR),Y
        BEQ     L182A
        TXA
        CMP     (KBDPTR),Y
        BEQ     L185D
        INY
        INY
        INY
        INY
        JMP     L1819

L182A:
        TXA
        CMP     #$00
        BEQ     L184F
        CMP     #$10
        BEQ     L185B
        CMP     #$20
        BCC     L184F
        CMP     #$41
        BCC     L184F
        CMP     #$5B
        BCC     L184D
        CMP     #$60
        BCC     L184F
        CMP     #$C1
        BCC     L185B
        CMP     #$DB
        BCC     L1854
        BCS     L185B

L184D:
        ORA     #$20

L184F:
        STA     CODE1
        CLC
        RTS

L1854:
        AND     #$7F
        STA     CODE1
        CLC
        RTS

L185B:
        SEC
        RTS

L185D:
        INY
        LDA     (KBDPTR),Y
        STA     CODE1
        INY
        LDA     (KBDPTR),Y
        STA     CODE2
        INY
        LDA     (KBDPTR),Y
        STA     CODE3
        CLC
        RTS

; Character table, runtime $1871-$188E, sitting straight after an RTS so a
; linear sweep runs into it and disassembles the bytes as instructions.
;
;     23 40 3B 7B 3A 7C 40 7D 2B 7E 5D 5B 5B 5C BA 5D 2D
;     00 DD 00 5E 00 DE 00 5C 00 A9 00 00 00
;
; The first run is # @ ; { : | @ } + ~ ] [ [ \ : ] - which are precisely the
; positions where the German and ASCII keyboard layouts differ - the same choice
; the "Keyboard: deutsch oder ASCII?" prompt offers. The tail pairs each $00 with
; a high-bit code ($DD, $DE, $A9), which look like the PETSCII characters those
; positions map to.
;
; Read as a layout translation table on that basis, and the code confirms the
; shape: $17D2 points KBDPTR here and then walks it with
;
;     LDA (KBDPTR),Y / BEQ done      $00 ends the table
;     TXA / CMP (KBDPTR),Y / BEQ hit
;     INY / INY                       two bytes per entry
;
; so it is a two-byte-per-entry lookup terminated by $00. Which byte is the
; input and which the output is not established, and the pairing across the
; whole table has not been decoded.
c64AsciiKeys:
        FCC     "#@;{:|@}+~][["
        FCB     $5C,$BA,$5D,$2D,$00,$DD,$00,$5E,$00,$DE,$00,$5C,$00,$A9,$00,$00
        FCB     $00

c64SendByte:
; vector 6 $1012 - push A into the 64-byte C64->decoder ring at btxTxFifo, spinning while it is full, then run c64CtrlThrottle
        LDX     btxXferDone
        CPX     btxXferDone
        BNE     c64SendByte
        CPX     #$00
        BEQ     c64SendByte

L189B:
        LDX     btxTxWr
        INX
        CPX     #$40
        BNE     L18A5
        LDX     #$00

L18A5:
        CPX     btxTxRd
        BEQ     L189B
        CPX     btxTxRd
        BEQ     L189B
        LDY     btxTxWr
        STA     btxTxFifo,Y
        STX     btxTxWr
        JSR     DELAY
        RTS

c64GetByteWait:
; vector 7 $1015 - c64GetByte in a loop: block until the decoder delivers a byte
        JSR     VONBTX
        BCS     c64GetByteWait
        RTS

c64GetByte:
; vector 8 $1018 - pull one byte from the 32-byte decoder->C64 ring at btxRxFifo. C=1 when empty. Read pointers twice to ride out metastability
        LDA     btxRxRd
        CMP     btxRxWr
        BEQ     L18CF
        CMP     btxRxWr
        BNE     L18D1

L18CF:
        SEC
        RTS

L18D1:
        TAX
        LDA     btxRxFifo,X
        INX
        CPX     #$20
        BNE     L18DC
        LDX     #$00

L18DC:
        STX     btxRxRd
        CLC
        RTS

c64HideMsg:
; vector 9 $101B - send $10 $7A $10 $55: close the status-line overlay and put the BTX page back
        LDA     #$10
        JSR     TOBTX
        LDA     #$7A
        JSR     TOBTX
        LDA     #$10
        JSR     TOBTX
        LDA     #$55
        JSR     TOBTX
        RTS

c64CaptureEnd:
; vector 10 $101E - STOP during a capture: send $10 $6D, wait for the transfer to drain, record the end pointer and offer c64SaveBuffer
        BIT     CAPFLG
        BPL     L192F
        LDA     #$10
        JSR     TOBTX
        LDA     #$6D
        JSR     TOBTX
        LDA     #$00
        STA     CAPFLG

L190A:
        LDA     btxXferEn
        BNE     L190A
        LDA     btxXferEn
        BNE     L190A
        JSR     CAPROU
        JSR     STLEER
        LDA     CAPPTR
        STA     CAPBIS
        LDA     CAPPTRHi
        STA     CAPBIS+1
        LDA     #$07                    ; msgSaveFile
        JSR     STAMSG
        JSR     SAVPUF
        JSR     OLDST

L192F:
        RTS

c64CtrlThrottle:
; vector 11 $1021 - poll keyboard row 7 for CTRL ($DC01 = $FB) and burn ~2000 cycles while it is held: the classic hold-to-slow-output
        LDA     #$7F
        STA     $DC00
        LDA     $DC01
        CMP     #$FB
        PHP
        LDA     #$7F
        STA     $DC00
        PLP
        BNE     L194D
        LDX     #$0A

L1945:
        LDY     #$C8

L1947:
        DEY
        BNE     L1947
        DEX
        BNE     L1945

L194D:
        RTS

c64Menu:
; vector 4 $100C - the <F7> menu: shows msgMenu1 or msgMenu2, reads a letter and dispatches through c64MenuKeys; any other key toggles the two menu lines
        LDA     #$00
        STA     MENFLG

L1953:
; msgMenu1, unless MENFLG picks msgMenu2 below
        LDA     #$03
        LDX     MENFLG
        BEQ     L195C
        LDA     #$04                    ; msgMenu2

L195C:
        JSR     STAMSG

L195F:
        JSR     GETAST
        AND     #$7F
        BEQ     L195F
        CMP     #$03
        BNE     L196D
        JMP     OLDST

L196D:
        STA     HELP01
        LDY     #$FD

L1972:
        INY
        INY
        INY
        LDA     c64MenuKeys,Y
        BEQ     L198C
        CMP     HELP01
        BNE     L1972
        LDA     c64MenuKeys+1,Y
        STA     ZPHELP
        LDA     c64MenuKeys+2,Y
        STA     ZPHELPHi
        JMP     (ZPHELP)

L198C:
        LDA     MENFLG
        EOR     #$FF
        STA     MENFLG
        JMP     L1953

; Menu key dispatch: records of one ASCII key byte then a 16-bit handler
; address, terminated by $00.
;
;     'L' -> $102D    'C' -> $103C    'D' -> $1042    'M' -> $1039
;     'X' -> $1045    'A' -> $1024    'B' -> $1027    'S' -> $1048
;     'K' -> $104E    'P' -> $1051    'E' -> $1054    'Q' -> $102A
;     'T' -> $10AB
;
; The keys are the highlighted letters of the two menu lines - "Load Capture
; Display Macro Xfer Screen" and "ASCII Btx Keybd Telesoft Edit Pause Quit" -
; and every target is an entry in the jump table at $1000, so this is what turns
; a keypress into a command.
c64MenuKeys:
        FCB     $4C                    ; 'L'
        DW      FILDIS
        FCB     $43                    ; 'C'
        DW      CAPTUR
        FCB     $44                    ; 'D'
        DW      DISCAP
        FCB     $4D                    ; 'M'
        DW      MAKEXE
        FCB     $58                    ; 'X'
        DW      TEXT
        FCB     $41                    ; 'A'
        DW      ASCII
        FCB     $42                    ; 'B'
        DW      BTX
        FCB     $53                    ; 'S'
        DW      SCREEN
        FCB     $4B                    ; 'K'
        DW      KEYBD
        FCB     $50                    ; 'P'
        DW      PAUSE
        FCB     $45                    ; 'E'
        DW      EDIT
        FCB     $51                    ; 'Q'
        DW      QUIT
        FCB     $54                    ; 'T'
        DW      TSW
        FCB     $00

c64MenuAscii:
; vector 12 $1024 - menu 'A' (ASCII): send $10 $67 and set the alpha-mode flag, which adds c64AsciiKeys to the front of c64XlatKey's search chain
        LDA     #$10
        JSR     TOBTX
        LDA     #$67
        JSR     TOBTX
        LDA     #$FF
        STA     c64AlphaFlag
        RTS

c64MenuBtx:
; vector 13 $1027 - menu 'B' (Btx): send $10 $66 and clear the alpha-mode flag
        LDA     #$10
        JSR     TOBTX
        LDA     #$66
        JSR     TOBTX
        LDA     #$00
        STA     c64AlphaFlag
        RTS

c64MenuQuit:
; vector 14 $102A - menu 'Q' (Quit): send ceptMonitorMsg ("C-64 - Betrieb ... Monitor an den Rechner umstecken"), close the drive command channel and JMP (KERNAL_RESET)
        JSR     OLDST
        LDA     #$00
        STA     btxFifo00
        LDA     #$10
        JSR     TOBTX
        LDA     #$4C
        JSR     TOBTX
        LDA     #$10
        JSR     TOBTX
        LDA     #$66
        JSR     TOBTX
        LDA     #$41
        STA     ZPHELP
        LDA     #$1A
        STA     ZPHELPHi

L1A03:
        LDY     #$00
        LDA     (ZPHELP),Y
        BEQ     L1A15
        JSR     TOBTX
        INC     ZPHELP
        BNE     L1A03
        INC     ZPHELPHi
        JMP     L1A03

L1A15:
        LDA     #$02
        JSR     PAUSAS
        LDA     #$10
        JSR     TOBTX
        LDA     #$51
        JSR     TOBTX
        LDA     #$02
        JSR     PAUSAS
        JSR     UNLSN
        LDA     #$08
        JSR     LISTN
        LDA     #$EF
        JSR     SECND
        JSR     UNLSN
        LDA     #$00
        STA     btxCartCtrl
        JMP     (KERNAL_RESET)

; CEPT datastream, not C64 screen text.
;
; The payload composes pages in the decoder's own protocol and sends them across
; rather than drawing on the C64 screen, so these blocks read as control codes
; mixed with text:
;
;     $1F r c   US, then row and column - CEPT cursor positioning
;     $9B ...   CSI, the C1 introducer the firmware dispatches at $D289
;     $1B ...   ESC, dispatched at $D1C9
;     $12 c n   RPT, repeat a character - ctlRPT at $DB2B in the firmware
;
; Three of them exist:
;
;   ceptMonitorMsg  $BDE9  "C-64 - Betrieb", then positioned lines
;                          "falls noetig,", "Monitor an den Rechner",
;                          "umstecken"
;   ceptMacroDir    $CD17  "Makro-Verzeichnis"
;   ceptStartPage   $CF65  the startup page: "commodore" in text followed by
;                          G1 mosaic characters ($A0-$DF) drawn with RPT runs,
;                          which is why it looks like noise as bytes. It ends
;                          with "V1.6 141087wr" - the C64 payload's own version
;                          and a date, 14 October 1987, plus what look like
;                          author initials. That is a different version line
;                          from the firmware's "Decodersoftware V3.3" at $EFF5,
;                          so the two halves are versioned separately.
;
; That the C64 side speaks CEPT to the decoder is what makes ctlRPT and the
; mosaic set visible from both directions - the firmware decodes exactly what
; this data encodes.
ceptMonitorMsg:
        FCB     $1F,$2F,$41,$9B,$31,$40,$1B,$23,$20,$57,$9B,$30,$40,$1F
        FCC     "EA   "
        FCB     $8F,$08
        FCC     " C-64 - Betrieb"
        FCB     $1F
        FCC     "KNfalls n"
        FCB     $C8
        FCC     "otig,"
        FCB     $1F
        FCC     "MIMonitor an den Rechner"
        FCB     $1F
        FCC     "OOumstecken"
        FCB     $00

c64MenuLoad:
; vector 15 $102D - menu 'L' (Load): msg 0 "von Diskette: File?", then stream the file to the decoder through c64DiskOpenRead/GetByte/CloseRead
        JSR     STLEER
        LDA     #$00                    ; msgLoadFile
        JSR     STAMSG
        LDA     #$13
        JSR     NAMEIN
        BCC     L1AAE
        JSR     OLDST
        RTS

L1AAE:
        JSR     OPRD
        BCC     L1AC1
        LDA     #$02                    ; msgNoFile
        JSR     STAMSG

L1AB8:
        JSR     GETAST
        BCS     L1AB8
        JSR     OLDST
        RTS

L1AC1:
        TXA
        PHA
        LDA     #$10
        JSR     TOBTX
        LDA     #$4C
        JSR     TOBTX
        PLA
        CMP     #$10
        BEQ     L1AD5
        JSR     TOBTX

L1AD5:
        JSR     VONIEC
        BCS     L1B05
        CMP     #$10
        BEQ     L1AF0
        PHA
        JSR     TOBTX
        PLA
        CMP     #$11
        BNE     L1AF0
        BIT     STATUS
        BVS     L1AF0
        LDA     #$05
        JSR     PAUSAS

L1AF0:
        BIT     STATUS
        BVC     L1AD5

L1AF4:
        JSR     CLORD
        JSR     OLDST
        LDA     #$10
        JSR     TOBTX
        LDA     #$6C
        JSR     TOBTX
        RTS

L1B05:
        BIT     MAKFLG
        BPL     L1AF4
        JSR     CLMR
        LDA     #$00
        STA     MAKFLG
        LDA     #$10
        JSR     TOBTX
        LDA     #$2E
        JSR     TOBTX
        JSR     OLDST
        JMP     L1AF4

c64MenuMacro:
; vector 19 $1039 - menu 'M' (Macro): msg $0B, read a macro id ('0'-'9','A'-'Z') or '?' for c64MacroDir, then send $08 $20 <id> $00 to the decoder and play the macro back
        LDA     #$00
        STA     STATUS
        LDA     #$08
        JSR     LISTN
        BIT     STATUS
        BMI     L1B38
        LDA     #$6F
        JSR     SECND
        BIT     STATUS
        BPL     L1B4B

L1B38:
; msgNoDrive
        LDA     #$0D
        JSR     STAMSG
        LDA     #$17                    ; msgPressKey
        JSR     STAMSG

L1B42:
        JSR     GETAST
        BCS     L1B42
        JSR     OLDST
        RTS

L1B4B:
        JSR     UNLSN
        JSR     FSCLR
        JSR     STLEER
        LDA     #$0B                    ; msgMacroRun
        JSR     STAMSG

L1B59:
        JSR     GETAST
        CMP     #$03
        BNE     L1B69
        LDA     #$00
        JSR     TOBTX
        JSR     OLDST
        RTS

L1B69:
        CMP     #$3F
        BEQ     L1B71
        CMP     #$DB
        BNE     L1B7C

L1B71:
        LDA     #$00
        JSR     TOBTX
        JSR     KATLOG
        JMP     MAKEXE

L1B7C:
        CMP     #$30
        BCC     L1B59
        CMP     #$3A
        BCC     L1B8E
        AND     #$7F
        CMP     #$41
        BCC     L1B59
        CMP     #$5B
        BCS     L1B59

L1B8E:
        STA     MAKNR
        LDA     #$08
        JSR     TOBTX
        LDA     #$20
        JSR     TOBTX
        LDA     MAKNR
        JSR     TOBTX
        LDA     #$00
        JSR     TOBTX
        BIT     EDTFLG
        BPL     L1BBD
        JSR     CLMW
        LDA     #$10
        JSR     TOBTX
