        BEQ     L22BE
        CMP     #$04
        BEQ     L22D3
        LDA     #$2A
        JMP     L230A

L228B:
        LDA     CAR
        CMP     #$20
        BEQ     L22EC
        CMP     #$50
        BNE     L229B
        LDA     #$C0
        JMP     L230A

L229B:
        CMP     #$24
        BNE     L22A4
        LDA     #$24
        JMP     L230A

L22A4:
        CMP     #$26
        BNE     L22AD
        LDA     #$23
        JMP     L230A

L22AD:
        LDA     #$2A
        JMP     L230A

L22B2:
        LDA     CAR
        CMP     #$20
        BEQ     L22EC
        LDA     #$2A
        JMP     L230A

L22BE:
        LDA     CAR
        CMP     #$20
        BEQ     L22EC
        CMP     #$50
        BNE     L22CE
        LDA     #$DD
        JMP     L230A

L22CE:
        LDA     #$2A
        JMP     L230A

L22D3:
        LDA     CAR
        CMP     #$20
        BEQ     L22EC
        CMP     #$40
        BCS     L22E3
        LDA     #$BF
        JMP     L230A

L22E3:
        CMP     #$60
        BCC     L22EC
        LDA     #$2A
        JMP     L230A

L22EC:
        LDA     CAR
        CMP     #$60
        BNE     L22F8
        LDA     #$20
        JMP     L230A

L22F8:
        CMP     #$7C
        BNE     L2301
        LDA     #$DD
        JMP     L230A

L2301:
        LDA     CAR
        CMP     #$41
        BCC     L230A
        EOR     #$20

L230A:
        PLP
        RTS

c64OpenPrinter:
; vector 49 $1093 - OPEN 1,4,7 and send ESC @ / ESC 3 $18: the hardcopy printer channel; msg $0F "Kein Drucker" on failure
        LDA     #$01
        STA     LA
        LDA     #$04
        STA     FA
        LDA     #$67
        STA     SA
        LDA     #$00
        STA     STATUS
        LDA     #$00
        STA     FNLEN
        JSR     OPENI
        LDA     FA
        JSR     LISTN
        LDA     SA
        JSR     SECND
        BIT     STATUS
        BMI     L234C
        LDA     #$1B
        JSR     CIOUT
        LDA     #$40
        JSR     CIOUT
        LDA     #$1B
        JSR     CIOUT
        LDA     #$33
        JSR     CIOUT
        LDA     #$18
        JSR     CIOUT
        CLC
        RTS

L234C:
        JSR     UNLSN
        JSR     STLEER
        LDA     #$0F                    ; msgNoPrinter
        JSR     STAMSG
        SEC
        RTS

; The payload's IRQ handler, installed into CINV.
;
;     BIT btxIrqCtrl / BMI ...     test a decoder register
;     JSR L104B                   a jump-table entry
;     JMP KEY                     chain to the KERNAL handler
;
; So the C64 side services the decoder on interrupt as well as polling it, and
; either passes the interrupt on to the KERNAL or consumes it. btxIrqCtrl is one
; of the registers whose function is otherwise unestablished; that the handler
; tests it first says it carries a request or status bit.
L2359:
        BIT     btxIrqCtrl
        BMI     L2364
        JSR     HORROU
        JMP     KEY

L2364:
        JSR     HORROU
        PLA
        TAY
        PLA
        TAX
        PLA
        RTI

c64GetKey:
; vector 53 $109F - fetch the next key: from the macro file during playback, otherwise GETIN. Applies the QWERTZ Y/Z swap and echoes to the macro file while recording. C=1 when nothing is pending
        LDA     MAKFLG
        BNE     L23BE
        JSR     GETIN
        CMP     #$00
        BEQ     L23BC
        CMP     #$A0
        BNE     L237F
        LDA     #$20

L237F:
        BIT     DTKBD
        BPL     L2396
        CMP     #$59
        BEQ     L2394
        CMP     #$5A
        BEQ     L2394
        CMP     #$D9
        BEQ     L2394
        CMP     #$DA
        BNE     L2396

L2394:
        EOR     #$03

L2396:
        BIT     EDTFLG
        BPL     L23A8
        PHA
        JSR     MKROUT
        PLA
        PHA
        JSR     CIOUT
        JSR     UNLSN
        PLA

L23A8:
        CMP     #$0D
        BNE     L23BA

L23AC:
        LDX     btxStatusMsg
        CPX     btxStatusMsg
        BNE     L23AC
        CPX     #$28
        BEQ     L23BA
        LDA     #$8D

L23BA:
        CLC
        RTS

L23BC:
        SEC
        RTS

L23BE:
        JSR     STOP
        BNE     L23C8
        LDA     #$00
        JMP     L23D7

L23C8:
        JSR     MKRIN
        JSR     VONIEC
        PHP
        PHA
        JSR     UNTLK
        PLA
        PLP
        BVC     L23F8

L23D7:
        PHA
        LDA     #$00
        JSR     TOBTX
        JSR     OLDST
        LDA     #$00
        STA     MAKFLG
        LDA     #$10
        JSR     TOBTX
        LDA     #$2E
        JSR     TOBTX
        JSR     OLDST
        JSR     CLMR
        PLA
        CLC
        RTS

L23F8:
        TXA
        CMP     #$01
        BNE     L2402
        JSR     WTCON
        SEC
        RTS

L2402:
        CLC
        RTS

; c64LoadExtra, and the format of BTX-EXTRA.MAS.
;
; Keyboard row 7 is scanned for CTRL at the end of the cold start - $DC01 = $FB,
; double-read the way everything here is - and if it is not held the routine
; returns at once. Held, it waits two seconds, opens "BTX-EXTRA.MAS" on device 8
; and reads it.
;
; The file is an ordinary CBM .prg and nothing more:
;
;     byte 0   load address, low
;     byte 1   load address, high
;     2..EOI   the data, stored from that address upward
;
; There is no length, no checksum and no header beyond those two bytes; the copy
; loop runs until VONIEC reports EOI. The filename carries no ,P,R
; suffix, so CBM DOS opens it as PRG by default and the two address bytes arrive
; as ordinary data on channel 4.
;
; What makes it more than a load is the last instruction:
;
;     JSR CLORD
;     JSR OLDST
;     JMP (CAPPTR)
;
; CAPPTR and CAPPTRHi were given the load address alongside ZPHELP and
; ZPHELPHi, and only ZPHELP is advanced by the copy - so the pair still holds
; where the file began, and the file is EXECUTED at its own load address. It is
; the same trick c64CartStart uses to reach the payload, with ZPHELP for the
; copy and an untouched second copy for the jump.
;
; So BTX-EXTRA.MAS is a self-contained program, free to choose where it lands,
; and this is the whole extension mechanism: hold CTRL at power-on. Nothing on
; screen mentions it. Status message 25, "Zusatzsoftware wird geladen", is shown
; while it loads.
c64LoadExtra:
; hold CTRL at power-on to load BTX-EXTRA.MAS from disk - keyboard row 7, $DC01 = $FB. Released, it returns at once
        LDA     #$7F
        STA     $DC00
        LDA     $DC01
        CMP     #$FB
        PHP
        LDA     #$7F
        STA     $DC00
        PLP
        BNE     L2463
        LDA     #$02
        JSR     PAUSAS
        LDX     #$00

L241E:
        LDA     c64ExtraFile,X
        BEQ     L2429
        STA     FNAME,X
        INX
        BNE     L241E

L2429:
        STX     NAMCTR
        JSR     OPRD
        BCS     L2460
        STA     ZPHELP
        STA     CAPPTR
        JSR     VONIEC
        BVS     L2460
        STA     ZPHELPHi
        STA     CAPPTRHi
        LDA     #$19                    ; msgLoadingExtra
        JSR     STAMSG

L2443:
        JSR     VONIEC
        BVS     L2457
        BCS     L2460
        LDY     #$00
        STA     (ZPHELP),Y
        INC     ZPHELP
        BNE     L2454
        INC     ZPHELPHi

L2454:
        JMP     L2443

L2457:
        JSR     CLORD
        JSR     OLDST
        JMP     (CAPPTR)

L2460:
        JSR     CLORD

L2463:
        RTS

; Filename of the extra software: "BTX-EXTRA.MAS", null-terminated.
;
; Loaded from disk when the user picks Telesoft, which is what the status
; message "Zusatzsoftware wird geladen" refers to. It sits immediately after an
; RTS, so a linear sweep runs straight into it and disassembles the characters
; as instructions.
c64ExtraFile:
        FCC     "BTX-EXTRA.MAS"
        FCB     $00

c64ShowSplash:
; vector 54 $10A2 - print c64SplashText on the C64 screen, then set the background and fill colour RAM
        LDA     #c64SplashText&255
        STA     SCNPTR
        LDA     #c64SplashText>>8
        STA     SCNPTRHi

L247A:
        LDY     #$00
        LDA     (SCNPTR),Y
        BEQ     L248B
        JSR     BSOUT
        INC     SCNPTR
        BNE     L247A
        INC     SCNPTRHi
        BNE     L247A

L248B:
        LDA     #$0F
        STA     $D021
        LDY     #$00
        LDA     #$0B

L2494:
        STA     $D800,Y
        STA     $D900,Y
        STA     $DA00,Y
        STA     $DB00,Y
        INY
        BNE     L2494
        RTS

; Startup screen text, PETSCII, ROM $C84C-$C94C (runtime $24A4-$25A4).
;
; Opens with $0E $08 $93 - switch to lower case, disable the Shift+Commodore
; case toggle, clear screen - then the message, with $0D for line breaks and
; $11 for cursor-down. Letters that appear as high-bit values ($CD, $C2, $D3 and
; so on) are shifted PETSCII, so the text reads:
;
;     BILDSCHIRMTEXT
;     BITTE STECKEN SIE IHREN MONITOR
;     AN DAS BTX-MODUL AN,
;     ODER WAEHLEN SIE DIE EINGE-
;     SCHRAENKTE TEXTDARSTELLUNG
;     MIT "<F7> S".
;     SIE VERLASSEN BTX MIT "<F7> Q".
;
; So the module tells the user to plug a monitor into the decoder itself, and
; offers a reduced text-only mode on the C64 screen as the alternative - which
; is what the separate 8x10 narrow font at $9E00 is for.
c64SplashText:
        CHARSET $41,$5A,$C1
        CHARSET $61,$7A,$41
        FCB     $0E,$08,$93,$97,$11,$11,$11
        FCC     "            Bildschirmtext"
        FCB     $0D,$11,$11,$11,$11
        FCC     "   Bitte stecken Sie Ihren Monitor"
        FCB     $0D
        FCC     "   an das Btx-Modul an,"
        FCB     $0D,$0D
        FCC     "   oder waehlen Sie die einge-"
        FCB     $0D
        FCC     "   schraenkte Textdarstellung"
        FCB     $0D
        FCC     "   mit "
        FCB     $22
        FCC     "<F7> S"
        FCB     $22,$2E,$0D,$0D
        FCC     "   Sie verlassen Btx mit "
        FCB     $22
        FCC     "<F7> Q"
        FCB     $22,$2E,$0D,$0D,$0D,$0D,$0D
        FCC     "----------------------------------------"
        FCB     $00
        CHARSET

c64PlotChar:
; vector 55 $10A5 - poke screen code A at column Y of row X, using the KERNAL screen-line tables LDTB2 (low bytes) and LDTB1 (line flags, whose low nibble carries the page)
        PHP
        SEI
        PHA
        TXA
        PHA
        LDA     LDTB2,Y
        STA     SCNPTR
        LDA     >LDTB1,Y
        AND     #$0F
        STA     SCNPTRHi
        PLA
        TAY
        PLA
        STA     (SCNPTR),Y
        PLP
        RTS

c64SetCursor:
; vector 56 $10A8 - set PNTR/TBLX and call STUPT; X = $FF instead re-enables the cursor blink
        PHP
        SEI
        CPX     #$FF
        BEQ     L25D0
        STX     PNTR
        STY     TBLX
        LDA     #$00
        STA     BLNSW
        JSR     STUPT
        PLP
        RTS

L25D0:
        LDA     #$01
        STA     BLNSW
        PLP
        RTS

c64DiskShowError:
; vector 38 $1072 - read the DOS error channel, msg 9, and forward the message text to the decoder for display. C=1 when the code is not 00
        LDA     #$00
        STA     STATUS
        LDA     #$08
        STA     FA
        JSR     TALK
        BIT     STATUS
        BMI     L2650
        LDA     #$6F
        STA     SA
        JSR     TKSA
        JSR     STLEER
        LDA     #$09                    ; msgErrLine
        JSR     STAMSG
        LDA     #$00
        STA     ERRFLG
        JSR     VONIEC
        BCS     L2648
        BVS     L2648
        CMP     #$30
        BEQ     L2609
        LDA     #$FF
        STA     ERRFLG

L2609:
        JSR     VONIEC
        BCS     L2648
        BVS     L2648
        CMP     #$30
        BEQ     L261C
        LDA     #$FF
        ORA     ERRFLG
        STA     ERRFLG

L261C:
        JSR     VONIEC
        BCS     L2648
        BVS     L2648

L2623:
        JSR     VONIEC
        BCS     L2648
        BVS     L2648
        CMP     #$2C
        BEQ     L263C
        TAX
        LDA     STATUS
        LSR     A
        LSR     A
        BCS     L2623
        TXA
        JSR     TOBTX
        JMP     L2623

L263C:
        LDA     #$00
        JSR     TOBTX

L2641:
        JSR     VONIEC
        BCS     L2648
        BVC     L2641

L2648:
        JSR     UNTLK
        BIT     ERRFLG
        BPL     L2652

L2650:
        SEC
        RTS

L2652:
        CLC
        RTS

c64DiskCheckError:
; vector 39 $1075 - read and discard the DOS error channel; C=1 when the code is not 00
        LDA     #$00
        STA     STATUS
        LDA     #$08
        STA     FA
        JSR     TALK
        LDX     STATUS
        BNE     L26A5
        LDA     #$6F
        STA     SA
        JSR     TKSA
        LDX     STATUS
        BNE     L26A5
        LDA     #$00
        STA     ERRFLG
        JSR     VONIEC
        BCS     L269D
        BVS     L269D
        CMP     #$30
        BEQ     L2683
        LDA     #$FF
        STA     ERRFLG

L2683:
        JSR     VONIEC
        BCS     L269D
        BVS     L269D
        CMP     #$30
        BEQ     L2696
        LDA     #$FF
        ORA     ERRFLG
        STA     ERRFLG

L2696:
        JSR     VONIEC
        BCS     L269D
        BVC     L2696

L269D:
        JSR     UNTLK
        BIT     ERRFLG
        BPL     L26A7

L26A5:
        SEC
        RTS

L26A7:
        CLC
        RTS

c64MacroRecStart:
; vector 47 $108D - OPEN "@:BTX-MAK-<id>,S,W" on device 8 channel 5 to begin recording a macro; msg $0D on failure
        LDY     #$0F
        STY     FNLEN
        LDA     #$02
        STA     LA
        LDA     #$08
        STA     FA
        LDA     #$65
        STA     SA
        LDA     #MAKNAM&255
        STA     FNADR
        LDA     #MAKNAM>>8
        STA     FNADR+1
        LDA     #$00
        STA     STATUS
        JSR     OPIEC
        BCC     L26D1
        LDA     #$0D                    ; msgNoDrive
        JSR     STAMSG
        SEC
        RTS

L26D1:
        JSR     FLOST
        BCS     L26D7
        RTS

L26D7:
        SEC
        RTS

c64MacroRecOpen:
; vector 34 $1066 - LISTN device 8 channel 5, the macro record file, and emit a $01 filler whenever the decoder's line counter btxPageCount has advanced
        LDA     #$02
        STA     LA
        LDA     #$08
        STA     FA
        LDA     #$65
        STA     SA
        LDA     FA
        JSR     LISTN
        LDA     SA
        JSR     SECND

L26EF:
        LDA     btxStatusMsg
        CMP     btxStatusMsg
        BNE     L26EF
        CMP     #$28
        BEQ     L2709

L26FB:
        LDA     btxPageCount
        CMP     btxPageCount
        BNE     L26FB
        STA     CONCTC
        JMP     L271E

L2709:
        LDA     btxPageCount
        CMP     btxPageCount
        BNE     L2709
        CMP     CONCTC
        BEQ     L271E
        LDA     #$01
        JSR     CIOUT
        INC     CONCTC

L271E:
        RTS

c64MacroTalk:
; vector 35 $1069 - TALK device 8 channel 6: make the macro file the talker for playback
        LDA     #$00
        STA     STATUS
        LDA     #$08
        STA     FA
        JSR     TALK
        LDA     #$66
        STA     SA
        JSR     TKSA
        RTS

c64OpenPrgWrite:
; vector 60 $10B4 - append ",P,W" to the filename and OPEN it on device 8 channel 4, then share c64OpenSeqWrite's tail
        LDY     NAMCTR
        LDA     #$2C
        STA     FNAME,Y
        INY
        LDA     #$50
        STA     FNAME,Y
        INY
        LDA     #$2C
        STA     FNAME,Y
        INY
        LDA     #$57
        STA     FNAME,Y
        INY
        STY     FNLEN
        JMP     L276F

c64OpenSeqWrite:
; vector 48 $1090 - append ",S,W" to the filename and OPEN it on device 8 channel 4
        LDY     NAMCTR
        LDA     #$2C
        STA     FNAME,Y
        INY
        LDA     #$53
        STA     FNAME,Y
        INY
        LDA     #$2C
        STA     FNAME,Y
        INY
        LDA     #$57
        STA     FNAME,Y
        INY
        STY     FNLEN

L276F:
        JSR     UNLSN
        JSR     UNTLK
        LDA     #$08
        STA     FA
        LDA     #$64
        STA     SA
        LDA     #FNAME&255
        STA     FNADR
        LDA     #FNAME>>8
        STA     FNADR+1
        LDA     #$00
        STA     STATUS
        JSR     OPIEC
        BCS     L27AD
        JSR     FLOST
        BCC     L2795
        SEC
        RTS

L2795:
        LDA     #$08
        STA     FA
        LDA     #$64
        STA     SA
        LDA     FA
        JSR     LISTN
        LDA     SA
        JSR     SECND
        LDA     FA
        STA     DFLTO
        CLC
        RTS

L27AD:
        JSR     STLEER
        LDA     #$0D                    ; msgNoDrive
        JSR     STAMSG
        SEC
        RTS

c64MacroOpenRead:
; vector 50 $1096 - open "@:BTX-MAK-<id>" on device 8 channel 6 for reading, via the shared tail of c64DiskOpenRead
        LDA     #$00
        STA     STATUS
        LDA     #$03
        STA     LA
        LDA     #$08
        STA     FA
        LDA     #$66
        STA     SA
        LDA     #MAKNAM&255
        STA     FNADR
        LDA     #MAKNAM>>8
        STA     FNADR+1
        LDA     #$0B
        STA     FNLEN
        JMP     L28C3

c64MacroDir:
; vector 51 $1099 - send ceptMacroDir ("Makro-Verzeichnis") and list every macro '0'-'9' then 'A'-'Z' with c64MacroDirLine
        BIT     MAKFLG
        BMI     L2845
        LDA     #$10
        JSR     TOBTX
        LDA     #$4C
        JSR     TOBTX
        LDA     MAKPIC
        STA     ZPHELP
        LDA     MAKPIC+1
        STA     ZPHELPHi

L27EF:
        LDY     #$00
        LDA     (ZPHELP),Y
        BEQ     L2801
        JSR     TOBTX
        INC     ZPHELP
        BNE     L27EF
        INC     ZPHELPHi
        JMP     L27EF

L2801:
        LDA     #$30
        STA     MAKNR

L2806:
        JSR     DISNAM
        BCS     L2833
        JSR     STOP
        BEQ     L2833
        INC     MAKNR
        LDA     MAKNR
        CMP     #$3A
        BNE     L2806
        LDA     #$41
        STA     MAKNR

L281F:
        JSR     DISNAM
        BCS     L2833
        JSR     STOP
        BEQ     L2833
        INC     MAKNR
        LDA     MAKNR
        CMP     #$5B
        BNE     L281F

L2833:
        JSR     STOP
        BEQ     L2833
        JSR     FSCLR
        LDA     #$10
        JSR     TOBTX
        LDA     #$6C
        JSR     TOBTX

L2845:
        RTS

c64MacroDirLine:
; vector 52 $109C - one directory line: "<id>: " followed by the first 17 characters of that macro file, padded with spaces, or dashes when it does not exist
        LDA     MAKNR
        JSR     TOBTX
        LDA     #$3A
        JSR     TOBTX
        LDA     #$20
        JSR     TOBTX
        LDA     #$11
        STA     HELP02
        JSR     OPMKRO
        BCS     L287B
        TXA
        JSR     SENCOD
        DEC     HELP02

L2867:
        JSR     VONIEC
        BCS     L28A5
        BVS     c64PadLine
        CMP     #$00
        BEQ     c64PadLine
        JSR     SENCOD
        DEC     HELP02
        BNE     L2867
        RTS

L287B:
        LDA     #$2D
        JSR     TOBTX
        DEC     HELP02
        LDA     HELP02
        CMP     #$0B
        BNE     L287B

L288A:
        LDA     #$20
        JSR     TOBTX
        DEC     HELP02
        BNE     L288A
        CLC
        RTS

c64PadLine:
; pad the rest of the directory line with spaces, then close the macro file
        LDA     #$20
        JSR     TOBTX
        DEC     HELP02
        BNE     c64PadLine
        JSR     CLMR
        CLC
        RTS

L28A5:
        JSR     c64PadLine
        SEC
        RTS

c64DiskOpenRead:
; vector 16 $1030 - open the named file on device 8 channel 4 for reading, TALK/TKSA, return the first byte in X. Shares the tail with c64MacroOpenRead
        LDA     #$00
        STA     STATUS
        LDA     #$08
        STA     FA
        LDA     #$64
        STA     SA
        LDA     #FNAME&255
        STA     FNADR
        LDA     #FNAME>>8
        STA     FNADR+1
        LDA     NAMCTR
        STA     FNLEN

L28C3:
        JSR     UNTLK
        JSR     UNLSN
        JSR     OPIEC
        BCS     L28EB
        LDA     SA
        STA     HELP03
        JSR     FSCLR
        BCS     L28EB
        LDA     FA
        JSR     TALK
        LDA     HELP03
        STA     SA
        JSR     TKSA
        JSR     VONIEC
        TAX
        CLC
        RTS

L28EB:
        SEC
        RTS

c64DiskGetByte:
; vector 17 $1033 - ACPTR one byte with a STOP check; C=1 on abort, V mirrors the EOI bit of STATUS
        LDA     #$00
        STA     STATUS

L28F1:
        LDA     #$FD
        AND     STATUS
        STA     STATUS
        JSR     STOP
        BEQ     L290B
        JSR     ACPTR
        TAX
        LDA     STATUS
        LSR     A
        LSR     A
        BCS     L28F1
        TXA
        BIT     STATUS
        CLC
        RTS

L290B:
        SEC
        RTS

c64CloseWrite:
; vector 33 $1063 - CLOSE device 8 channel 4: finish the file opened by c64OpenSeqWrite or c64OpenPrgWrite
        JSR     UNLSN
        LDA     #$08
        JSR     LISTN
