        LDA     #$64
        STA     SA
        JSR     CLSEI
        RTS

c64OpenChannel:
; vector 59 $10B1 - the shared open primitive: LISTN, SECND with SA | $F0, then fall into the KERNAL OPEN body at OP35
        LDA     #$00
        STA     STATUS
        LDA     FA
        JSR     LISTN
        LDA     STATUS
        BMI     L296A
        LDA     SA
        ORA     #$F0
        JSR     SECND
        LDA     STATUS
        BPL     L296C

L296A:
        SEC
        RTS

L296C:
        JMP     OP35

