c64TelesoftByte:
; vector 58 $10AE - the telesoftware reader: fill the ring buffer from the decoder and hand out one decoded byte, tracking the '<'/'>' framing and the 6-bit pair encoding
        JSR     VONBTX
        BCS     L2B3A
        LDY     #$00
        STA     (CAPPTR),Y
        INC     CAPPTR
        BNE     c64TelesoftByte
        INC     CAPPTRHi
        LDA     CAPPTRHi
        CMP     CAPENDHi
        BNE     c64TelesoftByte
        LDA     CAPPUF
        STA     CAPPTR
        LDA     CAPPUF+1
        STA     CAPPTRHi
        JMP     c64TelesoftByte

L2B3A:
        LDA     btxStatusMsg
        CMP     #$50
        BEQ     L2B50
        JSR     GETAST
        BCS     L2B55
        CMP     #$03
        BEQ     L2B50
        JSR     SENCOD
