        PLA
        JMP     L2AEE

L2B55:
        LDA     CAPPTR
        CMP     TSWPTR
        BNE     L2B64
        LDA     CAPPTRHi
        CMP     TSWPTRHi
        BNE     L2B64
        JMP     c64TelesoftByte

L2B64:
        LDY     #$00
        LDA     (TSWPTR),Y
        INC     TSWPTR
        BNE     L2B7F
        INC     TSWPTRHi
        LDX     TSWPTRHi
        CPX     CAPENDHi
        BNE     L2B7F
        LDX     CAPPUF
        STX     TSWPTR
        LDX     CAPPUF+1
        STX     TSWPTRHi

L2B7F:
        CMP     #$1F
        BEQ     L2BBB
        BIT     FLG314
        BPL     L2BB9
        LDX     INDEX
        BNE     L2B96
        STA     HIBITS
        INC     INDEX
        JMP     L2B3A

