        AND     #$3F
        ASL     A
        ASL     A
        STA     HIBITS
        AND     #$C0
        ORA     TSWHLP
        INC     INDEX
        LDX     INDEX
        CPX     #$04
        BNE     L2BB9
        LDX     #$00
